<?php
declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';require_role(['admin','collector','expert']);require_once __DIR__.'/../app/Services/CsvImporter.php';
$types=['computer'=>'کامپیوتر','printer'=>'چاپگر','display'=>'نمایشگر','scanner'=>'اسکنر'];$type=(string)($_GET['type']??$_POST['asset_type']??'computer');if(!isset($types[$type]))$type='computer';if(!can_manage_asset_type($type,'create')){http_response_code(403);exit('برای ثبت این نوع تجهیز دسترسی ندارید.');}$importer=new CsvImporter();$data=$_SESSION['_asset_import']??[];$error=null;$arrayFields=CsvImporter::arrayFields();
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['upload_csv'])){verify_csrf();if(empty($_FILES['csv']['tmp_name'])||$_FILES['csv']['error']!==UPLOAD_ERR_OK)$error='فایل CSV انتخاب نشده یا قابل دریافت نیست.';else try{$rows=$importer->rows($_FILES['csv']['tmp_name']);$row=$rows->current();if(!$row)throw new RuntimeException('فایل داده‌ای ندارد.');if(in_array($type,['printer','scanner'],true)){$row['IPAddresses']=[];unset($row['MACAddresses']);}$safe=bin2hex(random_bytes(16)).'.csv';if(!move_uploaded_file($_FILES['csv']['tmp_name'],upload_storage_dir().'/'.$safe))throw new RuntimeException('ذخیره امن فایل ناموفق بود.');$data=$row;$data['_source_file']=basename($_FILES['csv']['name']);$data['_source_path']=$safe;$data['_asset_type']=$type;$_SESSION['_asset_import']=$data;audit('hardware_csv_preview','asset',null,['file'=>$data['_source_file'],'type'=>$type]);}catch(Throwable $e){$error=$e->getMessage();}}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['save_asset'])){verify_csrf();$assetNo=trim((string)($_POST['asset_no']??''));if(!preg_match('/^\d{7}$/',$assetNo))$error='شماره اموال باید دقیقاً ۷ رقم باشد.';else{$check=db()->prepare('SELECT asset_no FROM assets WHERE asset_no=?');$check->execute([$assetNo]);if($check->fetchColumn()){flash('warning','شماره اموال تکراری است؛ اطلاعات همان تجهیز برای ویرایش باز شد.');redirect('asset_edit.php?asset_no='.urlencode($assetNo));}else try{$technical=[];foreach((array)($_POST['technical']??[]) as $k=>$v){$s=trim((string)$v);if(in_array($k,$arrayFields,true)){if($s===''){$technical[$k]=[];continue;}$decoded=json_decode($s,true);$technical[$k]=(json_last_error()===JSON_ERROR_NONE&&is_array($decoded))?array_values($decoded):$importer->split($s);}else$technical[$k]=$s;}$st=db()->prepare('INSERT INTO assets(asset_no,asset_type,device_subtype,hostname,personnel_id,location,manufacturer,model,serial_no,technical,status,source_file,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute([$assetNo,$type,trim((string)($_POST['device_subtype']??'')),trim((string)($_POST['hostname']??'')),($_POST['personnel_id']??'')!==''?(int)$_POST['personnel_id']:null,trim((string)($_POST['location']??'')),trim((string)($_POST['manufacturer']??'')),trim((string)($_POST['model']??'')),trim((string)($_POST['serial_no']??'')),json_encode($technical,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE),$_POST['status']??'active',(string)($_POST['_source_path']??$_POST['_source_file']??''),user()['id'],user()['id']]);foreach($importer->disks($data) as $d){$q=db()->prepare('INSERT INTO asset_disks(asset_no,disk_index,model,size_gb,serial_no,interface_name,media) VALUES(?,?,?,?,?,?,?)');$q->execute([$assetNo,$d['index'],$d['model'],$d['size_gb'],$d['serial_no'],$d['interface']??null,$d['media']??null]);}foreach($importer->ramSlots($data) as $r){$q=db()->prepare('INSERT INTO asset_ram_slots(asset_no,slot_no,state,capacity_gb,ram_type,speed_mhz,manufacturer,part_number,serial_no) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$assetNo,$r['slot_no'],$r['state']??'unknown',$r['capacity_gb']??null,$r['ram_type']??null,$r['speed_mhz']??null,$r['manufacturer']??null,$r['part_number']??null,$r['serial_no']??null]);}unset($_SESSION['_asset_import']);audit('asset_created','asset',$assetNo,['type'=>$type]);flash('success','تجهیز با موفقیت ثبت شد.');redirect('asset_view.php?asset_no='.urlencode($assetNo));}catch(Throwable $e){$error=$e->getMessage();}}}
$people=db()->query('SELECT id,full_name,personnel_code FROM personnel ORDER BY full_name LIMIT 5000')->fetchAll();$val=fn($k,$d='')=>$_POST[$k]??$data[$k]??$d;$display=function($key)use($val,$arrayFields,$importer){$v=$val($key);if(in_array($key,$arrayFields,true)){if(is_array($v))return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);$d=json_decode((string)$v,true);return is_array($d)?json_encode($d,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT):json_encode($v===''?[]:$importer->split((string)$v),JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);}return is_array($v)?json_encode($v,JSON_UNESCAPED_UNICODE):(string)$v;};
$fields=['computer'=>['SystemType'=>'نوع سیستم','OSName'=>'سیستم‌عامل','OSVersion'=>'نسخه سیستم‌عامل','OSBuild'=>'Build سیستم‌عامل','OSArchitecture'=>'معماری','CPUName'=>'پردازنده','CPUManufacturer'=>'سازنده CPU','CPUCores'=>'هسته فیزیکی','CPULogicalProcessors'=>'پردازنده منطقی','CPUMaxClockMHz'=>'فرکانس CPU (MHz)','GPUDetails'=>'کارت گرافیک','RAMTotalGB'=>'RAM کل (GB)','RAMSlotCount'=>'تعداد اسلات RAM','MotherboardManufacturer'=>'سازنده مادربرد','MotherboardProduct'=>'مدل مادربرد','MotherboardVersion'=>'نسخه مادربرد','MotherboardSerial'=>'سریال مادربرد','BIOSManufacturer'=>'سازنده BIOS','BIOSVersion'=>'نسخه BIOS','BIOSSerial'=>'سریال BIOS','BIOSReleaseDate'=>'تاریخ BIOS','Domain'=>'دامین / Workgroup','AntivirusDetails'=>'آنتی‌ویروس','NetworkDetails'=>'جزئیات کامل شبکه','SoundDetails'=>'صدا','PageFileDetails'=>'Page File'],'printer'=>['PrinterType'=>'نوع چاپگر','PrinterCapabilities'=>'قابلیت‌ها','ColorMode'=>'رنگی/سیاه‌وسفید','Connection'=>'نوع اتصال','IPAddresses'=>'IP (ورود دستی)','NetworkSharing'=>'اشتراک‌گذاری شبکه','Duplex'=>'چاپ دورو'],'display'=>['DisplayTechnology'=>'فناوری نمایشگر','DisplaySize'=>'اندازه نمایشگر','DisplayResolution'=>'رزولوشن','DisplaySerial'=>'سریال نمایشگر','Connection'=>'نوع اتصال'],'scanner'=>['ScannerType'=>'نوع اسکنر','ScannerResolution'=>'رزولوشن اسکنر','ScannerConnection'=>'اتصال اسکنر','ScannerDuplex'=>'اسکن دورو','IPAddresses'=>'IP (ورود دستی)']];
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ثبت <?=e($types[$type])?></title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">HWiNFO · پایش سخت‌افزار</a><nav><a href="index.php">داشبورد</a><a href="assets.php?type=<?=$type?>"><?=e($types[$type])?></a><a href="report.php">گزارش‌ها</a><?php if((user()['role']??'')==='admin'):?><a href="users.php">کاربران</a><a href="directory.php">Active Directory</a><?php endif;?><a href="logout.php">خروج</a></nav></header><main><div class="page-head"><div><h1>ثبت <?=e($types[$type])?></h1><p class="muted">فیلدها متناسب با نوع تجهیز و در چند ستون نمایش داده می‌شوند.</p></div></div><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><section class="panel"><h2>۱. تحلیل خروجی HWiNFO</h2><form method="post" enctype="multipart/form-data" class="upload-row"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="asset_type" value="<?=e($type)?>"><input type="file" name="csv" accept=".csv,text/csv" required><button class="btn" name="upload_csv" value="1">تحلیل CSV</button></form><?php if($data):?><p class="muted">فایل تحلیل‌شده: <?=e($data['_source_file']??'')?>.</p><?php endif;?></section><form method="post" class="panel" id="asset-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="save_asset" value="1"><input type="hidden" name="asset_type" value="<?=e($type)?>"><input type="hidden" name="_source_file" value="<?=e($val('_source_file'))?>"><input type="hidden" name="_source_path" value="<?=e($val('_source_path'))?>"><h2>۲. مشخصات پایه</h2><div class="form-grid"><label>شماره اموال *<input id="asset-no" name="asset_no" value="<?=e($val('asset_no'))?>" inputmode="numeric" pattern="\d{7}" maxlength="7" required><div id="duplicate-check" class="duplicate-check"></div></label><label>زیرنوع دستگاه<input name="device_subtype" value="<?=e($val('device_subtype'))?>"></label><label>نام دستگاه / Hostname<input name="hostname" value="<?=e($val('ComputerName'))?>"></label><label>کاربر اصلی / مسئول<select name="personnel_id"><option value="">انتخاب پرسنل</option><?php foreach($people as $p):?><option value="<?=$p['id']?>" <?=((string)$val('personnel_id')===(string)$p['id'])?'selected':''?>><?=e($p['full_name'].' — '.($p['personnel_code']??''))?></option><?php endforeach;?></select></label><label>مکان<input name="location" value="<?=e($val('location'))?>"></label><label>برند<input name="manufacturer" value="<?=e($val('Manufacturer'))?>"></label><label>مدل<input name="model" value="<?=e($val('Model'))?>"></label><label>شماره سریال<input name="serial_no" value="<?=e($val('SystemSerial'))?>"></label><label>وضعیت<select name="status"><option value="active">فعال</option><option value="repair">در تعمیر</option><option value="retired">اسقاط</option><option value="lost">مفقود</option></select></label></div><h2>۳. فیلدهای اختصاصی <?=e($types[$type])?></h2><div class="form-grid"><?php foreach($fields[$type] as $k=>$label):?><label><?=e($label)?><textarea name="technical[<?=e($k)?>]" rows="3" <?=in_array($k,$arrayFields,true)?'dir="ltr"':''?>><?=e($display($k))?></textarea></label><?php endforeach;?></div><div class="actions"><button class="btn primary" type="submit" id="save-button">ذخیره نهایی</button><a class="btn" href="assets.php?type=<?=$type?>">انصراف</a></div></form></main><script>const n=document.getElementById('asset-no'),box=document.getElementById('duplicate-check'),save=document.getElementById('save-button');let timer;async function checkAsset(){const v=n.value.trim();box.classList.remove('show');box.textContent='';save.disabled=false;if(!/^\d{7}$/.test(v))return;try{const r=await fetch('asset_check.php?asset_no='+encodeURIComponent(v),{credentials:'same-origin'});const d=await r.json();if(d.duplicate){box.innerHTML='<span>⚠️ شماره اموال قبلاً ثبت شده است ('+(d.type||'تجهیز')+').</span><a class="btn small" href="'+d.edit_url+'">ویرایش همین شماره اموال</a>';box.classList.add('show');save.disabled=true;}}catch(e){}}n.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(checkAsset,250)});n.addEventListener('blur',checkAsset);if(/^\d{7}$/.test(n.value))checkAsset();</script></body></html>
